import codecs
for name, data in (('ascii', b'\xffA'), ('utf_8', b'\xffA'), ('utf_7', b'+A!'), ('utf_16_le', b'\x00\xdcA\x00'), ('utf_32_le', b'\x00\x00\x11\x00A\x00\x00\x00'), ('unicode_escape', b'\x5cxZ'), ('raw_unicode_escape', b'\x5cuZ')):
    for outcome in ('return', 'negative', 'raise'):
        seen = []
        failure = ValueError('guest failure')
        def recover(error):
            input()
            seen.append((error.encoding, error.object, error.start, error.end, error.reason))
            if outcome == 'raise':
                raise failure
            return ('?', error.end if outcome == 'return' else -len(error.object)-1)
        codecs.register_error('snapshot-service', recover)
        try:
            print(name, outcome, getattr(codecs, name + '_decode')(data, 'snapshot-service'))
        except Exception as error:
            print(name, outcome, type(error).__name__, error.args, error is failure, error.__traceback__ is not None)
        print(seen)
